ALTER TABLE "post_images" ADD FOREIGN KEY ("image_id") REFERENCES "uploaded_images" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "post_likes" ADD FOREIGN KEY ("user_id") REFERENCES "users" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "post_likes" ADD FOREIGN KEY ("post_id") REFERENCES "posts" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "trades" ADD FOREIGN KEY ("post_id") REFERENCES "posts" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "trades" ADD FOREIGN KEY ("buyer_id") REFERENCES "users" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "trades" ADD FOREIGN KEY ("seller_id") REFERENCES "users" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "trades" ADD FOREIGN KEY ("canceled_by_id") REFERENCES "users" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "trades" ADD FOREIGN KEY ("buyer_inventory_item_id") REFERENCES "inventory_items" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "trade_reviews" ADD FOREIGN KEY ("trade_id") REFERENCES "trades" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "trade_reviews" ADD FOREIGN KEY ("writer_id") REFERENCES "users" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "trade_reviews" ADD FOREIGN KEY ("target_user_id") REFERENCES "users" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "credit_transactions" ADD FOREIGN KEY ("user_id") REFERENCES "users" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "credit_transactions" ADD FOREIGN KEY ("trade_id") REFERENCES "trades" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "credit_transactions" ADD FOREIGN KEY ("ai_waste_report_id") REFERENCES "ai_waste_reports" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "chat_rooms" ADD FOREIGN KEY ("post_id") REFERENCES "posts" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "chat_rooms" ADD FOREIGN KEY ("buyer_id") REFERENCES "users" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "chat_rooms" ADD FOREIGN KEY ("seller_id") REFERENCES "users" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "chat_participants" ADD FOREIGN KEY ("chat_room_id") REFERENCES "chat_rooms" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "chat_participants" ADD FOREIGN KEY ("user_id") REFERENCES "users" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "chat_participants" ADD FOREIGN KEY ("last_read_message_id") REFERENCES "chat_messages" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "chat_messages" ADD FOREIGN KEY ("chat_room_id") REFERENCES "chat_rooms" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "chat_messages" ADD FOREIGN KEY ("sender_id") REFERENCES "users" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "chat_messages" ADD FOREIGN KEY ("image_id") REFERENCES "uploaded_images" ("id") DEFERRABLE INITIALLY IMMEDIATE;

